"""Exact normalized homology of a submodule generated by one tensor."""

from dataclasses import dataclass
from fractions import Fraction
from itertools import combinations

import numpy as np
import sympy as sp
from sympy.polys.matrices import DomainMatrix

from .tensor_ops import face, split_normalized

__all__ = ["GeneratedHomology", "generated_homology", "relative_horn_homology"]


@dataclass(frozen=True)
class GeneratedHomology:
    """Dimensions in ascending degrees, extended by zero beyond the tuples."""

    chain_dimensions: tuple[int, ...]
    boundary_ranks: tuple[int, ...]
    homology_dimensions: tuple[int, ...]


def _exact_tensor(tensor: np.ndarray, modulus: int | None) -> np.ndarray:
    entries = []
    for value in tensor.flat:
        if isinstance(value, (bool, np.bool_)):
            value = int(value)
        if not isinstance(value, (int, np.integer, Fraction, sp.Rational)):
            raise TypeError("Exact homology requires integer or rational entries.")
        rational = sp.Rational(value)
        if modulus is None:
            entries.append(rational)
        else:
            try:
                inverse = pow(int(rational.q), -1, modulus)
            except ValueError as exc:
                raise ValueError("A coefficient denominator vanishes in the field.") from exc
            entries.append(int(rational.p) * inverse % modulus)
    return np.array(entries, dtype=object).reshape(tensor.shape)


def _column_rank(columns: list[np.ndarray], field) -> int:
    matrix = sp.Matrix(np.column_stack([column.ravel() for column in columns]).tolist())
    return DomainMatrix.from_Matrix(matrix).convert_to(field).rank()


def _normalized_columns(tensor: np.ndarray, degree: int) -> list[np.ndarray]:
    active = min(tensor.shape)
    tails = [list(range(active, length)) for length in tensor.shape]
    return [
        split_normalized(tensor[np.ix_(*(list(indices) + tail for tail in tails))])[0]
        for indices in combinations(range(active), degree + 1)
    ]


def _homology(tensor: np.ndarray, modulus: int | None, missing_face: int | None) -> GeneratedHomology:
    tensor = np.asarray(tensor)
    if tensor.ndim == 0 or min(tensor.shape) == 0:
        raise ValueError("Homology needs nonempty tensor axes.")
    if modulus is not None and (
        not isinstance(modulus, (int, np.integer))
        or isinstance(modulus, (bool, np.bool_)) or not sp.isprime(modulus)
    ):
        raise ValueError("The modulus must be prime.")
    modulus = int(modulus) if modulus is not None else None
    exact = _exact_tensor(tensor, modulus)
    field = sp.QQ if modulus is None else sp.GF(modulus)
    active = min(tensor.shape)
    subgenerators = []
    if missing_face is not None:
        if active < 2 or not 0 <= missing_face < active:
            raise ValueError("The omitted face must belong to a positive-degree horn.")
        subgenerators = [face(exact, i) for i in range(active) if i != missing_face]

    dimensions = []
    ranks = [0]
    subcolumns_below: list[np.ndarray] = []
    subrank_below = 0
    for degree in range(min(active - 1, tensor.ndim) + 1):
        columns = _normalized_columns(exact, degree)
        subcolumns = [col for face_tensor in subgenerators for col in _normalized_columns(face_tensor, degree)]
        subrank = _column_rank(subcolumns, field) if subcolumns else 0
        dimensions.append(_column_rank(columns, field) - subrank)
        if degree:
            images = [face(column, 0) for column in columns]
            ranks.append(_column_rank(images + subcolumns_below, field) - subrank_below)
        subcolumns_below, subrank_below = subcolumns, subrank

    homology = tuple(
        dimension - outgoing - incoming
        for dimension, outgoing, incoming in zip(dimensions, ranks, ranks[1:] + [0])
    )
    return GeneratedHomology(tuple(dimensions), tuple(ranks), homology)


def generated_homology(tensor: np.ndarray, *, modulus: int | None = None) -> GeneratedHomology:
    """Compute N(<tensor>) over Q, or over F_p for a supplied prime modulus.

    The tensor has at least one axis and all axes are nonempty. A tensor of
    shape s is a simplex of degree min(s)-1 in the unshifted DSTM with offsets
    s_a - min(s). Only normalized degrees up to min(degree, order) can survive.
    Boundary ranks are ranks of linear maps, indexed by their source degree.
    """
    return _homology(tensor, modulus, None)


def relative_horn_homology(
    tensor: np.ndarray, missing_face: int, *, modulus: int | None = None,
) -> GeneratedHomology:
    """Compute the normalized quotient by the submodule of the included faces."""
    if not isinstance(missing_face, (int, np.integer)):
        raise TypeError("The omitted face index must be an integer.")
    return _homology(tensor, modulus, int(missing_face))
